async function loadAssignees(){const d=await api('/assignees');$('#principalSelect').innerHTML='<option value="">Sélectionner un responsable</option>'+d.items.map(x=>'<option value="'+x.id+'">'+esc(x.display_name)+' — '+esc(x.role)+'</option>').join('');}
async function loadDocuments(){
 const params=new URLSearchParams();for(const [id,key] of [['documentYear','year'],['documentCategory','category'],['documentSubcategory','subcategory'],['documentType','document_type'],['documentProject','project']]){const value=$('#'+id).value?.trim();if(value)params.set(key,value);}
 const data=await api('/documents'+(params.size?'?'+params.toString():'')),items=data.items||[];
 const typeLabels={ordre_service:'Ordre de service',reception_provisoire:'PV de réception provisoire',reception_definitive:'PV de réception définitive',market_commission_pv:'PV commission des marchés'};
 const rows=items.map(d=>{const url='/api/projects/'+encodeURIComponent(d.project_id)+'/documents/'+d.id+'/download';const preview=['application/pdf','image/jpeg','image/png'].includes(d.mime_type);return '<tr><td>'+esc(typeLabels[d.document_type]||d.document_type||'Type non renseigné')+'</td><td><b>'+esc(d.project_code)+'</b><br>'+esc(d.project_title)+'</td><td><b>'+esc(d.original_filename)+'</b><div class="document-file-actions">'+(preview?'<button type="button" class="secondary" data-document-preview="'+url+'" data-document-title="'+esc(d.original_filename)+'">Aperçu</button>':'')+' <a href="'+url+'">Télécharger</a></div></td></tr>';}).join('');
 $('#documentRows').innerHTML=rows||'<tr><td colspan="3" class="muted">Aucun document ne correspond aux filtres.</td></tr>';$('#documentCount').textContent=items.length+' document(s)';
 const fill=(id,values,allLabel)=>{const el=$('#'+id),v=el.value;el.innerHTML='<option value="">'+allLabel+'</option>'+values.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');if(values.includes(v))el.value=v;};
 const projects=allProjects||[];fill('documentYear',[...new Set(projects.map(p=>p.initial_programming_year).filter(Boolean))].sort((a,b)=>a-b),'Toutes les années');fill('documentCategory',[...new Set(projects.map(p=>p.category).filter(Boolean))].sort(),'Toutes les catégories');const cat=$('#documentCategory').value;fill('documentSubcategory',[...new Set(projects.filter(p=>!cat||p.category===cat).map(p=>p.subcategory).filter(Boolean))].sort(),'Toutes les sous-catégories');
 $('#documentRows').querySelectorAll('[data-document-preview]').forEach(btn=>btn.addEventListener('click',()=>{const dialog=$('#documentPreviewDialog');$('#documentPreviewTitle').textContent=btn.dataset.documentTitle||'Aperçu du document';$('#documentPreviewFrame').src=btn.dataset.documentPreview+'?inline=1';dialog.showModal();}));
}
function geometryTypeLabel(t){return t==='Point'?'Point':t==='LineString'?'Polyligne':'Polygone';}
function geometryStyle(g){const c=g?.properties?.color||'#2479a8';return {color:c,weight:4,fillColor:c,fillOpacity:.2};}
const gisSymbolIcons={monument:'🏛️',building:'🏢',school:'🎓',sport:'🏟️',health:'✚',water:'💧',road:'🛣️',other:'📍'};
function gisPointIcon(properties={}){const color=/^#[0-9a-fA-F]{6}$/.test(properties.color||'')?properties.color:'#64748b',symbol=gisSymbolIcons[properties.symbol]||gisSymbolIcons.other;return L.divIcon({className:'gis-marker-icon',html:'<span style="background:'+color+'"><i>'+symbol+'</i></span>',iconSize:[34,34],iconAnchor:[17,17],tooltipAnchor:[0,-17]});}
function initGisMap(){
 if(gisMap)return;
 gisMap=L.map('projectMap',{referrerPolicy:'strict-origin-when-cross-origin'}).setView([32.93,10.45],9);
 const baseLayers={
  streets:L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri — Sources: Esri, HERE, Garmin, USGS, Intermap, INCREMENT P, NRCan, Esri Japan, METI, Esri China, GeoTechnologies, Inc., and the GIS User Community'}),
  satellite:L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community'}),
  osm:L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'})
 };
 baseLayers.streets.addTo(gisMap);
 const basemapSelect=document.getElementById('gisBasemap');
 if(basemapSelect)basemapSelect.addEventListener('change',()=>{Object.values(baseLayers).forEach(layer=>{if(gisMap.hasLayer(layer))gisMap.removeLayer(layer);});const selected=baseLayers[basemapSelect.value]||baseLayers.streets;selected.addTo(gisMap);});
 gisLayers=new L.FeatureGroup().addTo(gisMap);
 if(currentUser.role==='admin'||currentUser.role==='technical'){gisMap.addControl(new L.Control.Draw({draw:{polyline:{shapeOptions:geometryStyle()},polygon:{allowIntersection:false,showArea:true,shapeOptions:geometryStyle()},marker:true,rectangle:false,circle:false,circlemarker:false},edit:{featureGroup:gisLayers,remove:true}}));}
 gisMap.on(L.Draw.Event.CREATED,e=>{if(!$('#gisProject').value){alert('Sélectionnez d’abord le projet auquel rattacher cet objet.');return;}gisPending=e.layer;gisLayers.addLayer(e.layer);gisActive=null;$('#gisFeatureForm').classList.remove('hidden');$('#gisFeatureForm').dataset.featureId='';$('#gisFeatureForm').elements.label.value='';$('#gisFeatureForm').elements.description.value='';$('#gisFeatureForm').elements.symbol.value='other';$('#gisFeatureForm').elements.color.value='#64748b';$('#gisFeatureForm').querySelector('.form-message').textContent='Nouvel objet : '+geometryTypeLabel(e.layer.toGeoJSON().geometry.type)+'. Renseignez son nom puis enregistrez.';});
 gisMap.on(L.Draw.Event.EDITED,async e=>{for(const layer of e.layers.getLayers()){const d=layer._gisData;if(!d)continue;try{const geometry=layer.toGeoJSON().geometry;await api('/geometries/'+d.id,{method:'PUT',body:JSON.stringify({...d,geometry,geometry_type:geometry.type})});}catch(err){alert('Modification cartographique non enregistrée : '+err.message);}}await loadGis(false);});
 gisMap.on(L.Draw.Event.DELETED,async e=>{for(const layer of e.layers.getLayers()){const d=layer._gisData;if(d)try{await api('/geometries/'+d.id,{method:'DELETE'});}catch(err){alert(err.message);}}await loadGis(false);});
}
async function loadGis(refreshProjects=true){
 if(refreshProjects||!allProjects.length){const d=await api('/dashboard');allProjects=d.items||[];}
 initGisMap();const select=$('#gisProject'),selected=select.value;select.innerHTML='<option value="">Tous les projets</option>'+allProjects.map(p=>'<option value="'+p.id+'">'+esc(p.project_code)+' — '+esc(p.title)+'</option>').join('');select.value=selected;
 const data=await api('/geometries');gisRecords=data.items||[];gisLayers.clearLayers();const projectId=select.value,type=$('#gisTypeFilter').value;const visible=gisRecords.filter(g=>(!projectId||String(g.project_id)===projectId)&&(!type||g.geometry_type===type));
 visible.forEach(g=>{const layer=L.geoJSON(g.geometry,{style:()=>geometryStyle(g),pointToLayer:(_f,ll)=>L.marker(ll,{icon:gisPointIcon(g.properties||{})})}).getLayers()[0];if(!layer)return;layer._gisData=g;layer.bindTooltip('<b>'+esc(g.label)+'</b><br>'+esc(g.project_code)+' — '+esc(g.project_title),{sticky:true});layer.on('click',()=>openProject(g.project_id));gisLayers.addLayer(layer);});
 $('#gisCount').textContent=visible.length+' objet(s) géographique(s)';
 $('#gisFeatureList').innerHTML=visible.length?visible.map(g=>'<div class="gis-feature"><button type="button" class="link gis-select-feature" data-gis-feature="'+g.id+'"><b>'+esc(g.label)+'</b><small>'+esc(g.project_code)+' · '+geometryTypeLabel(g.geometry_type)+'</small></button>'+(currentUser.role==='admin'||currentUser.role==='technical'?'<button type="button" class="secondary gis-edit-feature" data-gis-edit="'+g.id+'">Détails</button>':'')+'</div>').join(''):'<p class="muted">Aucun objet géographique pour ces critères. Utilisez les outils de dessin sur la carte pour en ajouter.</p>';
 document.querySelectorAll('[data-gis-feature]').forEach(btn=>btn.addEventListener('click',()=>{const g=visible.find(x=>String(x.id)===btn.dataset.gisFeature);const layer=gisLayers.getLayers().find(x=>x._gisData&&String(x._gisData.id)===btn.dataset.gisFeature);if(layer){const bounds=layer.getBounds?layer.getBounds():L.latLngBounds([layer.getLatLng()]);gisMap.fitBounds(bounds,{maxZoom:16});layer.openTooltip();}if(g)openProject(g.project_id);}));
 document.querySelectorAll('[data-gis-edit]').forEach(btn=>btn.addEventListener('click',()=>{const g=visible.find(x=>String(x.id)===btn.dataset.gisEdit);if(!g)return;gisPending=null;gisActive=g;$('#gisFeatureForm').dataset.featureId=g.id;$('#gisFeatureForm').classList.remove('hidden');$('#gisFeatureForm').elements.label.value=g.label;$('#gisFeatureForm').elements.description.value=g.description||'';$('#gisFeatureForm').elements.symbol.value=g.properties?.symbol||'other';$('#gisFeatureForm').elements.color.value=g.properties?.color||'#64748b';$('#gisFeatureForm').querySelector('.form-message').textContent='';}));
 const bounds=gisLayers.getBounds();if(projectId&&bounds.isValid())gisMap.fitBounds(bounds.pad(.15));else if(!gisMap._hasFitted){if(bounds.isValid())gisMap.fitBounds(bounds.pad(.12));gisMap._hasFitted=true;}setTimeout(()=>gisMap.invalidateSize(),80);
}
async function loadUsers(){
 const form=$('#userCreateForm'),host=$('#usersList'),message=$('#userCreateMessage');
 if(!form.dataset.submitBound){
  form.dataset.submitBound='1';
  form.addEventListener('submit',async e=>{
   e.preventDefault();
   const currentForm=e.currentTarget,data=Object.fromEntries(new FormData(currentForm).entries());
   message.textContent='';
   try{
    await api('/users',{method:'POST',body:JSON.stringify(data)});
    message.textContent='Compte créé.';
    currentForm.reset();
    await loadUsers();
   }catch(err){message.textContent=err.message;}
  });
 }
 const d=await api('/users');
 host.innerHTML='<div class="table-wrap"><table><thead><tr><th>Nom</th><th>Identifiant</th><th>Rôle</th><th>Actif</th></tr></thead><tbody>'+d.items.map(x=>'<tr><td>'+esc(x.display_name)+'</td><td>'+esc(x.username)+'</td><td>'+esc(x.role)+'</td><td>'+(x.is_active?'Oui':'Non')+'</td></tr>').join('')+'</tbody></table></div>';
}
function nav(page){document.querySelectorAll('.page').forEach(x=>x.classList.add('hidden'));$('#'+page+'Page').classList.remove('hidden');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageTitle').textContent=({dashboard:translations[currentLang].dashboard,projects:translations[currentLang].projects,documents:translations[currentLang].documents,gis:translations[currentLang].gis,users:translations[currentLang].users}[page]||page);if(page==='projects')loadProjects().catch(e=>alert(e.message));if(page==='documents')loadDocuments().catch(e=>alert(e.message));if(page==='gis')loadGis().catch(e=>alert(e.message));if(page==='users')loadUsers().catch(e=>alert(e.message));}
$('#languageSwitch').value=localStorage.getItem('pm-language')||'fr';applyLanguage($('#languageSwitch').value);$('#languageSwitch').addEventListener('change',e=>applyLanguage(e.target.value));
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';const f=new FormData(e.currentTarget);try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});currentUser=d.user;showApp();nav('dashboard');await loadDashboard();}catch(x){$('#loginError').textContent=x.message;}});
$('#logoutBtn').addEventListener('click',async()=>{await api('/auth/logout',{method:'POST'}).catch(()=>{});currentUser=null;showLogin();});
document.querySelectorAll('.nav').forEach(x=>x.addEventListener('click',()=>nav(x.dataset.page)));document.querySelectorAll('[data-goto]').forEach(x=>x.addEventListener('click',()=>nav(x.dataset.goto)));
$('#searchBtn').addEventListener('click',()=>loadProjects().catch(e=>alert(e.message)));$('#documentSearchBtn').addEventListener('click',()=>loadDocuments().catch(e=>alert(e.message)));$('#closeDocumentPreview').addEventListener('click',()=>{ $('#documentPreviewDialog').close();$('#documentPreviewFrame').src='about:blank';});$('#documentPreviewDialog').addEventListener('close',()=>{$('#documentPreviewFrame').src='about:blank';});$('#documentProject').addEventListener('keydown',e=>{if(e.key==='Enter')loadDocuments().catch(err=>alert(err.message));});$('#gisProject').addEventListener('change',()=>loadGis(false).catch(e=>alert(e.message)));$('#gisTypeFilter').addEventListener('change',()=>loadGis(false).catch(e=>alert(e.message)));$('#gisCancel').addEventListener('click',()=>{$('#gisFeatureForm').classList.add('hidden');if(gisPending)gisLayers.removeLayer(gisPending);gisPending=null;gisActive=null;});$('#gisFeatureForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,body={label:form.elements.label.value.trim(),description:form.elements.description.value,properties:{symbol:form.elements.symbol.value,color:form.elements.color.value}};try{if(gisPending){body.geometry=gisPending.toGeoJSON().geometry;body.geometry_type=body.geometry.type;await api('/projects/'+encodeURIComponent($('#gisProject').value)+'/geometries',{method:'POST',body:JSON.stringify(body)});gisPending=null;}else if(gisActive){body.geometry=gisActive.geometry;body.geometry_type=body.geometry.type;await api('/geometries/'+gisActive.id,{method:'PUT',body:JSON.stringify(body)});}form.classList.add('hidden');await loadGis(false);}catch(err){form.querySelector('.form-message').textContent=err.message;}});['#documentYear','#documentCategory','#documentSubcategory','#documentType'].forEach(sel=>$(sel).addEventListener('change',()=>loadDocuments().catch(e=>alert(e.message))));['#yearSearch','#statusSearch','#categorySearch'].forEach(sel=>$(sel).addEventListener('change',()=>loadProjects().catch(e=>alert(e.message))));$('#newProjectBtn').addEventListener('click',()=>{loadAssignees().then(()=>$('#projectDialog').showModal()).catch(e=>alert(e.message));});$('#cancelProject').addEventListener('click',()=>$('#projectDialog').close());$('#closeDetail').addEventListener('click',()=>$('#detailDialog').close());$('#dashboardYear').addEventListener('change',renderDashboard);
$('#projectForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/projects',{method:'POST',body:JSON.stringify({title:f.get('title'),year:Number(f.get('year'))||null,category:f.get('category'),updated_cost:Number(f.get('updated_cost'))||0,status:f.get('status'),principal_user_id:Number(f.get('principal_user_id'))})});$('#projectDialog').close();e.currentTarget.reset();await loadProjects();alert('Projet créé : '+d.project_code);}catch(x){$('#projectError').textContent=x.message;}});
(async()=>{try{const d=await api('/auth/me');currentUser=d.user;showApp();nav('dashboard');await loadDashboard();}catch{showLogin();}})();